def solve(data):
    jobs = data["jobs"]
    setup = data["setup"]
    blackouts = sorted([tuple(b) for b in data.get("blackouts", [])])
    n = len(jobs)
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    deps = []
    for j in jobs:
        d = set()
        ok = True
        for x in j.get("deps", []):
            if x not in idx or x == j["id"]:
                ok = False
                break
            d.add(idx[x])
        deps.append(d if ok else None)

    def earliest(s, dur):
        changed = True
        while changed:
            changed = False
            for a, b in blackouts:
                if a >= s + dur:
                    break
                if s < b and s + dur > a:
                    s = b
                    changed = True
        return s

    best = [0, 0, []]  # value, completion, seq

    def consider(val, comp, seq):
        if val > best[0] or (val == best[0] and (comp < best[1] or (comp == best[1] and seq < best[2]))):
            best[0], best[1], best[2] = val, comp, list(seq)

    def dfs(mask, t, f, val, seq):
        consider(val, t, seq)
        for i in range(n):
            if mask >> i & 1:
                continue
            d = deps[i]
            if d is None:
                continue
            if any(not (mask >> k & 1) for k in d):
                continue
            j = jobs[i]
            s = max(j["release"], t + setup[f][j["family"]])
            s = earliest(s, j["duration"])
            c = s + j["duration"]
            if c > j["deadline"]:
                continue
            seq.append(j["id"])
            dfs(mask | (1 << i), c, j["family"], val + j["value"], seq)
            seq.pop()

    dfs(0, 0, 0, 0, [])
    return best[2]

