import random
def peer(data):
    jobs = sorted(data['jobs'], key=lambda j: j['id'])
    n = len(jobs)
    index = {j['id']: i for i, j in enumerate(jobs)}
    deps = []
    for j in jobs:
        mask = 0
        for d in j.get('deps', []):
            mask |= 1 << index.get(d, n)
        deps.append(mask)
    blocks = []
    for a, b in sorted(data.get('blackouts', [])):
        if b <= a:
            continue
        if blocks and a <= blocks[-1][1]:
            blocks[-1][1] = max(blocks[-1][1], b)
        else:
            blocks.append([a, b])
    setup = data['setup']
    best = [0, 0, ()]
    path = []
    def visit(mask, time, family, value):
        seq = tuple(path)
        if value > best[0] or (value == best[0] and (time < best[1] or (time == best[1] and seq < best[2]))):
            best[0], best[1], best[2] = value, time, seq
        for i, j in enumerate(jobs):
            bit = 1 << i
            if mask & bit or deps[i] & ~mask:
                continue
            start = max(j['release'], time + setup[family][j['family']])
            duration = j['duration']
            for a, b in blocks:
                if start + duration <= a:
                    break
                if start < b and start + duration > a:
                    start = b
            end = start + duration
            if end <= j['deadline']:
                path.append(j['id'])
                visit(mask | bit, end, j['family'], value + j['value'])
                path.pop()
    visit(0, 0, 0, 0)
    return list(best[2])

def solve(data):
    jobs = data["jobs"]
    setup = data["setup"]
    blackouts = sorted([tuple(b) for b in data.get("blackouts", []) if b[1] > b[0]])
    n = len(jobs)
    idx = {j["id"]: i for i, j in enumerate(jobs)}
    deps = []
    for j in jobs:
        d = set(); ok = True
        for x in j.get("deps", []):
            if x not in idx or x == j["id"]:
                ok = False; break
            d.add(idx[x])
        deps.append(d if ok else None)
    def earliest(s, dur):
        changed = True
        while changed:
            changed = False
            for a, b in blackouts:
                if a >= s + dur: break
                if s < b and s + dur > a:
                    s = b; changed = True
        return s
    best = [0, 0, []]
    def consider(val, comp, seq):
        if val > best[0] or (val == best[0] and (comp < best[1] or (comp == best[1] and seq < best[2]))):
            best[0], best[1], best[2] = val, comp, list(seq)
    def dfs(mask, t, f, val, seq):
        consider(val, t, seq)
        for i in range(n):
            if mask >> i & 1: continue
            d = deps[i]
            if d is None: continue
            if any(not (mask >> k & 1) for k in d): continue
            j = jobs[i]
            s = max(j["release"], t + setup[f][j["family"]])
            s = earliest(s, j["duration"])
            c = s + j["duration"]
            if c > j["deadline"]: continue
            seq.append(j["id"])
            dfs(mask | (1 << i), c, j["family"], val + j["value"], seq)
            seq.pop()
    dfs(0, 0, 0, 0, [])
    return best[2]

def gen(seed):
    r = random.Random(seed)
    n = r.randint(0, 8)
    ids = ["j%d" % i for i in range(n)]
    jobs = []
    for i in range(n):
        deps = [r.choice(ids + ["zz"]) for _ in range(r.randint(0, 2))] if n else []
        jobs.append({"id": ids[i], "release": r.randint(0, 10), "duration": r.randint(1, 5), "deadline": r.randint(0, 25), "value": r.randint(1, 9), "family": r.randint(0, 2), "deps": deps})
    setup = [[r.randint(0, 3) for _ in range(3)] for _ in range(3)]
    bl = []
    for _ in range(r.randint(0, 4)):
        a = r.randint(0, 20); b = a + r.randint(0, 5)
        bl.append([a, b])
    return {"jobs": jobs, "setup": setup, "blackouts": bl}

